    '{n, plural, =1{# criterion needs a remark to say why it got that level.} other{# criteria need a remark to say why they got that level.}}' => '{n, plural, =1{# criterion needs a remark to say why it got that level.} other{# criteria need a remark to say why they got that level.}}',
